const grid=document.createElement('div');Object.assign(grid.style,{display:'grid',gridTemplateColumns:'repeat(12,30px)',gap:'2px',padding:'10px'});stage.appendChild(grid);let mines=new Set(),open=new Set(),flags=new Set(),start=0,over=false;metric('mines_remaining','20');metric('cells_discovered','0');metric('elapsed_time','0s');metric('game_state','RUNNING');state('LEFT: reveal - RIGHT: flag - R: new board');function neighbors(i){let x=i%12,y=i/12|0;return[-13,-12,-11,-1,1,11,12,13].map(d=>i+d).filter(j=>j>=0&&j<144&&Math.abs((j%12)-x)<=1)}function nearbyMines(i){return neighbors(i).filter(j=>mines.has(j)).length}function revealArea(startCell){let queue=[startCell],seen=new Set();while(queue.length){let i=queue.shift();if(seen.has(i)||open.has(i)||flags.has(i)||mines.has(i))continue;seen.add(i);open.add(i);if(nearbyMines(i)===0)neighbors(i).forEach(j=>{if(!seen.has(j)&&!mines.has(j))queue.push(j)})}}function draw(){grid.innerHTML='';for(let i=0;i<144;i++){let b=document.createElement('button'),near=nearbyMines(i);b.textContent=open.has(i)?(mines.has(i)?'':near||''):'';Object.assign(b.style,{height:'30px',border:'1px solid #34373d',background:open.has(i)?(mines.has(i)?'#f2495c':'#111217'):'#22252b',color:'#d8d9da',fontWeight:'700'});if(open.has(i)&&mines.has(i)){let bomb=document.createElement('span'),blastH=document.createElement('span'),blastV=document.createElement('span'),core=document.createElement('span'),fuse=document.createElement('span'),spark=document.createElement('span');Object.assign(bomb.style,{display:'inline-block',position:'relative',width:'17px',height:'17px',verticalAlign:'middle'});Object.assign(blastH.style,{position:'absolute',left:'0',top:'7px',width:'17px',height:'3px',borderRadius:'2px',background:'#ffc857'});Object.assign(blastV.style,{position:'absolute',left:'7px',top:'0',width:'3px',height:'17px',borderRadius:'2px',background:'#ffc857'});Object.assign(core.style,{position:'absolute',left:'3px',top:'3px',width:'11px',height:'11px',border:'2px solid #f5f7ff',borderRadius:'50%',background:'#15171c',boxSizing:'border-box'});Object.assign(fuse.style,{position:'absolute',left:'1px',top:'1px',width:'6px',height:'2px',background:'#f5f7ff',transform:'rotate(-35deg)',transformOrigin:'right center'});Object.assign(spark.style,{position:'absolute',left:'0',top:'0',width:'3px',height:'3px',borderRadius:'50%',background:'#ffc857'});bomb.append(blastH,blastV,core,fuse,spark);b.appendChild(bomb)}if(flags.has(i)){let marker=document.createElement('span'),pole=document.createElement('span'),pennant=document.createElement('span');Object.assign(marker.style,{display:'inline-block',position:'relative',width:'13px',height:'15px',verticalAlign:'middle'});Object.assign(pole.style,{position:'absolute',left:'2px',top:'0',width:'2px',height:'15px',background:'#d8d9da'});Object.assign(pennant.style,{position:'absolute',left:'4px',top:'1px',width:'10px',height:'8px',background:'#f2495c',clipPath:'polygon(0 0,100% 22%,0 100%)'});marker.append(pole,pennant);b.appendChild(marker)}b.onclick=()=>{if(over||flags.has(i))return;if(mines.has(i)){open.add(i);over=true;state('SLO BREACHED','#f2495c');set('game_state','LOST')}else{revealArea(i);if(open.size===144-mines.size){mines.forEach(x=>flags.add(x));over=true;state('ALL CLEAR - MINES FLAGGED');set('game_state','WON')}}draw()};b.oncontextmenu=e=>{e.preventDefault();if(!open.has(i)&&!over){flags.has(i)?flags.delete(i):flags.add(i);draw()}};grid.appendChild(b)}set('mines_remaining',20-flags.size);set('cells_discovered',open.size)}function newBoard(){mines=new Set();open=new Set();flags=new Set();while(mines.size<20)mines.add(Math.random()*144|0);start=Date.now();over=false;set('mines_remaining','20');set('cells_discovered','0');set('elapsed_time','0s');set('game_state','RUNNING');state('LEFT: reveal - RIGHT: flag - R: new board');draw()}restartButton.onclick=newBoard;root.addEventListener('keydown',e=>{if(e.key&&e.key.toLowerCase()==='r'){e.preventDefault();newBoard()}});elapsedTimer=s